CREATE OR REPLACE FUNCTION public.sb_save_answer(eid text,question text,reason text,fact_ids text[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;ev jsonb;result jsonb;allowed int; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; PERFORM public.sb_rate_limit(); IF NOT app_private.sb_event_visible(eid) THEN RAISE EXCEPTION 'event_not_found' USING ERRCODE='PT404'; END IF; IF length(trim(coalesce(question,''))) NOT BETWEEN 1 AND 2000 OR coalesce(reason,'') NOT IN ('current','changes','no_evidence','advice') OR coalesce(cardinality(fact_ids),0)>6 THEN RAISE EXCEPTION 'invalid_question' USING ERRCODE='PT422'; END IF; SELECT count(*) INTO allowed FROM public.facts f WHERE f.id=ANY(fact_ids) AND f.validation_status='supported' AND app_private.sb_fact_visible(f.id) AND (f.event_id=eid OR EXISTS(SELECT 1 FROM public.changes c WHERE c.event_id=eid AND c.previous_fact_id=f.id)); IF allowed<>coalesce(cardinality(fact_ids),0) OR (reason IN ('current','changes') AND allowed=0) OR (reason IN ('advice','no_evidence') AND allowed<>0) THEN RAISE EXCEPTION 'invalid_evidence' USING ERRCODE='PT422'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('source_id',f.id,'quote',f.quote,'source_url',d.source_url,'location',c.location) ORDER BY array_position(fact_ids,f.id)),'[]') INTO ev FROM public.facts f JOIN public.document_chunks c ON c.id=f.chunk_id JOIN public.documents d ON d.id=c.document_id WHERE f.id=ANY(fact_ids); result:=jsonb_build_object('status',CASE reason WHEN 'advice' THEN 'policy_blocked' WHEN 'no_evidence' THEN 'abstained' ELSE 'answered' END,'message',CASE reason WHEN 'current' THEN '질문과 관련된 검증된 원문 인용입니다. 새로운 해석이나 주가 전망을 생성하지 않았습니다.' WHEN 'changes' THEN '이전과 현재를 비교할 수 있는 원문 근거입니다. 각 인용의 기간과 단위를 함께 확인하세요.' WHEN 'advice' THEN '매매 추천, 목표주가, 확정적인 수익률 전망은 제공하지 않습니다. 공시의 사실과 변경점을 질문해 주세요.' ELSE '제공된 공시 근거만으로 이 질문에 답하기 어렵습니다. 확인되지 않은 내용은 추측하지 않습니다.' END,'evidence',ev,'run_id',NULL,'mode','extractive'); PERFORM 1 FROM public.users WHERE id=u FOR UPDATE; IF (SELECT count(*) FROM public.question_history WHERE user_id=u)>=2000 THEN RAISE EXCEPTION 'question_history_limit_delete_old_history' USING ERRCODE='PT422'; END IF; INSERT INTO public.question_history(user_id,event_id,question,answer) VALUES(u,eid,question,result); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.sb_save_answer(text,text,text,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_save_answer(text,text,text,text[]) TO authenticated;
DROP POLICY owner_select ON public.question_history; CREATE POLICY owner_select ON public.question_history FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid())::text AND app_private.sb_event_visible(event_id));
CREATE FUNCTION public.sb_clear_history() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ DELETE FROM public.question_history WHERE user_id=(SELECT auth.uid())::text $$;
REVOKE ALL ON FUNCTION public.sb_clear_history() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_clear_history() TO authenticated;
CREATE FUNCTION public.sb_track(event_name text,properties jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;k text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=u AND analytics_consent) THEN RETURN; END IF; PERFORM public.sb_rate_limit(); IF coalesce(event_name,'') NOT IN ('sign_up','login','onboarding_started','watchlist_added','onboarding_completed','brief_impression','brief_opened','evidence_opened','followup_asked','alert_created','feedback_submitted') OR jsonb_typeof(properties) IS DISTINCT FROM 'object' OR octet_length(properties::text)>1024 THEN RAISE EXCEPTION 'invalid_analytics' USING ERRCODE='PT422'; END IF; FOR k IN SELECT jsonb_object_keys(properties) LOOP IF k NOT IN ('event_id','company_id','screen','density') OR jsonb_typeof(properties->k)<>'string' OR length(properties->>k)>100 THEN RAISE EXCEPTION 'sensitive_analytics_property_denied' USING ERRCODE='PT422'; END IF; END LOOP; INSERT INTO public.user_events(id,user_id,event_name,properties,created_at) VALUES(gen_random_uuid()::text,u,event_name,properties::json,now()); END $$;
REVOKE ALL ON FUNCTION public.sb_track(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_track(text,jsonb) TO authenticated;
DO $$ DECLARE src text; BEGIN SELECT pg_get_functiondef('public.sb_user_action(text,jsonb)'::regprocedure) INTO src; src:=replace(src,'PERFORM public.sb_initialize_profile(); PERFORM 1','PERFORM public.sb_rate_limit(); PERFORM public.sb_initialize_profile(); PERFORM 1'); src:=replace(src,'WHEN ''chat_save'' THEN','WHEN ''chat_save'' THEN RAISE EXCEPTION ''use_evidence_bound_answer_rpc'' USING ERRCODE=''PT422'';'); EXECUTE src; END $$;
CREATE FUNCTION public.sb_ops_dashboard() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE result jsonb; BEGIN IF NOT app_private.sb_is_admin() THEN RAISE EXCEPTION 'admin_required' USING ERRCODE='PT403'; END IF; SELECT jsonb_build_object('metrics',jsonb_build_object('documents_total',(SELECT count(*) FROM public.documents),'documents_today',(SELECT count(*) FROM public.documents WHERE ingested_at>=date_trunc('day',now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul'),'events_total',(SELECT count(*) FROM public.events),'ai_runs_total',(SELECT count(*) FROM public.ai_runs),'ai_failures',(SELECT count(*) FROM public.ai_runs WHERE status='failed'),'needs_review',(SELECT count(*) FROM public.events WHERE state='needs_review'),'numeric_mismatches',(SELECT count(*) FROM public.validations WHERE status='numeric_mismatch'),'citation_failures',(SELECT count(*) FROM public.validations WHERE status IN ('missing_source','unsupported','conflicting_sources')),'open_user_reports',(SELECT count(*) FROM public.feedback WHERE state='open'),'known_cost_usd',(SELECT sum(cost_usd)::text FROM public.ai_runs),'runs_with_unknown_cost',(SELECT count(*) FROM public.ai_runs WHERE cost_usd IS NULL),'llm_latency_p95_ms',(SELECT percentile_cont(.95) WITHIN GROUP(ORDER BY latency_ms) FROM public.ai_runs WHERE latency_ms IS NOT NULL)),'event_statuses',coalesce((SELECT jsonb_object_agg(state,n) FROM (SELECT state,count(*) n FROM public.events GROUP BY state) t),'{}'),'validation_statuses',coalesce((SELECT jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM public.validations GROUP BY status) t),'{}'),'run_statuses',coalesce((SELECT jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM public.ai_runs GROUP BY status) t),'{}'),'cost_note','Known cost is a subtotal of recorded runs, not a bill or spending cap. Missing costs and latencies remain unknown. No synthetic operational metrics.','generated_at',now()) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.sb_ops_dashboard() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_ops_dashboard() TO authenticated; NOTIFY pgrst,'reload schema';